/**
 * Property-based tests.
 *
 * Only invariants that actually hold are asserted here. Functions in this
 * project that have none (prompt builders, formatters whose output is defined
 * by example) are covered by the example-based suites instead.
 */
import fc from 'fast-check';
import { describe, expect, it } from 'vitest';
import { decrypt, encrypt } from './crypto';
import { extractWordAtOffset, takeTranslationLine } from './exerciseContent';
import { omitUndefined } from './omitUndefined';

// aes-256-cbc needs exactly 32 bytes.
const KEY = '0123456789abcdef0123456789abcdef';

describe('encrypt / decrypt - reversibility', () => {
  it('decrypt undoes encrypt for any string', () => {
    fc.assert(
      fc.property(fc.string(), plaintext => {
        expect(decrypt(encrypt(plaintext, KEY), KEY)).toBe(plaintext);
      })
    );
  });

  it('holds for arbitrary unicode, including astral planes', () => {
    fc.assert(
      fc.property(fc.string({ unit: 'grapheme' }), plaintext => {
        expect(decrypt(encrypt(plaintext, KEY), KEY)).toBe(plaintext);
      })
    );
  });

  it('is non-deterministic: the same input yields a fresh ciphertext', () => {
    fc.assert(
      fc.property(fc.string({ minLength: 1 }), plaintext => {
        expect(encrypt(plaintext, KEY)).not.toBe(encrypt(plaintext, KEY));
      })
    );
  });
});

const jsonValue = fc.oneof(
  fc.string(),
  fc.integer(),
  fc.boolean(),
  fc.constant(null),
  fc.constant(undefined)
);
const anyRecord = fc.dictionary(fc.string(), jsonValue);

describe('omitUndefined - idempotence and key preservation', () => {
  it('is idempotent', () => {
    fc.assert(
      fc.property(anyRecord, record => {
        expect(omitUndefined(omitUndefined(record))).toEqual(omitUndefined(record));
      })
    );
  });

  it('keeps exactly the keys whose value is defined', () => {
    fc.assert(
      fc.property(anyRecord, record => {
        const expected = Object.keys(record).filter(key => record[key] !== undefined);
        expect(Object.keys(omitUndefined(record)).sort()).toEqual(expected.sort());
      })
    );
  });

  it('never invents or alters a value', () => {
    fc.assert(
      fc.property(anyRecord, record => {
        const result = omitUndefined(record) as Record<string, unknown>;
        for (const key of Object.keys(result)) {
          expect(result[key]).toBe(record[key]);
        }
      })
    );
  });

  it('leaves a record without undefined values unchanged', () => {
    const definedRecord = fc.dictionary(
      fc.string(),
      fc.oneof(fc.string(), fc.integer(), fc.boolean(), fc.constant(null))
    );
    fc.assert(
      fc.property(definedRecord, record => {
        expect(omitUndefined(record)).toEqual(record);
      })
    );
  });
});

describe('extractWordAtOffset - idempotence and containment', () => {
  const textAndOffset = fc
    .string()
    .chain(text => fc.tuple(fc.constant(text), fc.integer({ min: 0, max: text.length })));

  it('always returns a substring of the input', () => {
    fc.assert(
      fc.property(textAndOffset, ([text, offset]) => {
        expect(text).toContain(extractWordAtOffset(text, offset));
      })
    );
  });

  it('is idempotent: re-expanding from inside the word yields the same word', () => {
    fc.assert(
      fc.property(textAndOffset, ([text, offset]) => {
        const word = extractWordAtOffset(text, offset);
        if (word === '') return;

        const start = text.indexOf(word);
        expect(extractWordAtOffset(text, start)).toBe(word);
      })
    );
  });

  it('never returns a word containing a separator', () => {
    fc.assert(
      fc.property(textAndOffset, ([text, offset]) => {
        expect(extractWordAtOffset(text, offset)).not.toMatch(/\s/u);
      })
    );
  });
});

describe('takeTranslationLine - size preservation', () => {
  const lines = fc.array(fc.string());

  it('removes exactly one line when it returns a value, none otherwise', () => {
    fc.assert(
      fc.property(lines, input => {
        const working = [...input];
        const taken = takeTranslationLine(working);
        expect(working.length).toBe(input.length - (taken === null ? 0 : 1));
      })
    );
  });

  it('only ever returns null for an empty list', () => {
    fc.assert(
      fc.property(lines, input => {
        expect(takeTranslationLine([...input]) === null).toBe(input.length === 0);
      })
    );
  });

  it('keeps the remaining lines in their original order', () => {
    fc.assert(
      fc.property(lines, input => {
        const working = [...input];
        takeTranslationLine(working);
        expect(input.join('�')).toContain(working.slice(0, 1).join('�'));
      })
    );
  });
});

